-- Generated from full_report.txt on 2026-05-08.
-- Source user: ADMIN
-- Purpose: grant the ADMIN privilege footprint to a chosen target user on non-ADB Oracle environments.
-- If the target user already exists, its current grants/rights remain in place and this script only appends missing ADMIN-equivalent access.
-- Run this script as SYS AS SYSDBA.
-- The script prompts for the target user, password, and ORDS options at runtime.

set define on
set verify off
set feedback off
set serveroutput on size unlimited
set pagesize 0

prompt Enter ADMIN-like account details
accept TARGET_USERNAME char default 'ADMIN' prompt 'Enter target username [ADMIN]: '
accept TARGET_PASSWORD char HIDE prompt 'Enter password for target user: '
accept TARGET_PASSWORD_CONFIRM char HIDE prompt 'Confirm password for target user: '
accept ENABLE_ORDS char default 'Y' prompt 'Enable ORDS for this user? (Y/N) [Y]: '
accept ORDS_AUTO_REST_AUTH char default 'FALSE' prompt 'Enable ORDS auto REST auth? (TRUE/FALSE) [FALSE]: '

column PASSWORDS_MATCH new_value PASSWORDS_MATCH noprint
select case
         when '&&TARGET_PASSWORD' = '&&TARGET_PASSWORD_CONFIRM' then 'Y'
         else 'N'
       end as PASSWORDS_MATCH
  from dual;

begin
  if '&&PASSWORDS_MATCH' <> 'Y' then
    raise_application_error(-20001, 'Password entries did not match.');
  end if;
end;
/

variable summary_user_action varchar2(4000)
variable summary_password_action varchar2(4000)
variable summary_ords_action varchar2(4000)
variable summary_setup_failures varchar2(4000)
variable role_grants_attempted number
variable role_grants_failed number
variable summary_role_failures varchar2(4000)
variable sys_privs_attempted number
variable sys_privs_failed number
variable summary_sys_priv_failures varchar2(4000)
variable quota_changes_attempted number
variable quota_changes_failed number
variable summary_quota_failures varchar2(4000)
variable object_grants_attempted number
variable object_grants_failed number
variable object_apex_failures number
variable summary_object_grant_failures varchar2(4000)

begin
  :summary_user_action := 'No user changes were made.';
  :summary_password_action := 'Password unchanged.';
  :summary_ords_action := 'ORDS enablement not attempted.';
  :summary_setup_failures := null;
  :role_grants_attempted := 0;
  :role_grants_failed := 0;
  :summary_role_failures := null;
  :sys_privs_attempted := 0;
  :sys_privs_failed := 0;
  :summary_sys_priv_failures := null;
  :quota_changes_attempted := 0;
  :quota_changes_failed := 0;
  :summary_quota_failures := null;
  :object_grants_attempted := 0;
  :object_grants_failed := 0;
  :object_apex_failures := 0;
  :summary_object_grant_failures := null;
end;
/

prompt Verifying execution context
declare
begin
  if sys_context('USERENV', 'SESSION_USER') <> 'SYS' then
    raise_application_error(-20001, 'This script must be run as SYS AS SYSDBA.');
  end if;
  dbms_output.put_line('INFO: Running as SYS.');
end;
/

prompt Preparing profile and user
declare
  v_target_username     varchar2(128)  := upper(trim(q'[&&TARGET_USERNAME]'));
  v_target_user_q       varchar2(261);
  v_password            varchar2(4000) := q'[&&TARGET_PASSWORD]';
  v_default_ts          varchar2(128);
  v_temp_ts             varchar2(128);
  v_quota_ts            varchar2(128);
  v_exists              number;
  v_user_exists         number;
  v_cloud_verify_exists number;
  v_setup_failed        number := 0;
  v_setup_failures      varchar2(4000);

  procedure record_failure(p_sql in varchar2, p_err in varchar2) is
    v_entry varchar2(500);
  begin
    v_setup_failed := v_setup_failed + 1;
    v_entry := '[' || to_char(v_setup_failed) || '] ' || substr(p_sql, 1, 180) || ' -> ' || substr(p_err, 1, 180);
    if v_setup_failures is null then
      v_setup_failures := v_entry;
    elsif length(v_setup_failures) + length(v_entry) + 1 <= 3900 then
      v_setup_failures := v_setup_failures || chr(10) || v_entry;
    end if;
  end;

  procedure safe_exec(p_sql in varchar2) is
  begin
    execute immediate p_sql;
  exception
    when others then
      record_failure(p_sql, sqlerrm);
  end;

  function resolve_perm_ts(p_preferred in varchar2) return varchar2 is
    v_ts varchar2(128);
  begin
    begin
      select tablespace_name
        into v_ts
        from dba_tablespaces
       where contents = 'PERMANENT'
         and tablespace_name = p_preferred;
      return v_ts;
    exception
      when no_data_found then null;
    end;
    begin
      select tablespace_name
        into v_ts
        from dba_tablespaces
       where tablespace_name = 'USERS'
         and contents = 'PERMANENT';
      return v_ts;
    exception
      when no_data_found then null;
    end;
    select tablespace_name
      into v_ts
      from (
        select tablespace_name
          from dba_tablespaces
         where contents = 'PERMANENT'
         order by tablespace_name
      )
     where rownum = 1;
    return v_ts;
  end;

  function resolve_temp_ts(p_preferred in varchar2) return varchar2 is
    v_ts varchar2(128);
  begin
    begin
      select tablespace_name
        into v_ts
        from dba_tablespaces
       where contents = 'TEMPORARY'
         and tablespace_name = p_preferred;
      return v_ts;
    exception
      when no_data_found then null;
    end;
    begin
      select property_value
        into v_ts
        from database_properties
       where property_name = 'DEFAULT_TEMP_TABLESPACE';
      return v_ts;
    exception
      when no_data_found then null;
    end;
    select tablespace_name
      into v_ts
      from (
        select tablespace_name
          from dba_tablespaces
         where contents = 'TEMPORARY'
         order by tablespace_name
      )
     where rownum = 1;
    return v_ts;
  end;
begin
  if v_target_username is null then
    raise_application_error(-20000, 'TARGET_USERNAME must not be empty.');
  end if;
  v_target_user_q := dbms_assert.enquote_name(dbms_assert.simple_sql_name(v_target_username), false);
  v_default_ts := resolve_perm_ts('DATA');
  v_temp_ts := resolve_temp_ts('TEMP');
  v_quota_ts := resolve_perm_ts('DATA');
  if v_quota_ts is null then
    v_quota_ts := v_default_ts;
  end if;
  if v_default_ts <> 'DATA' then
    dbms_output.put_line('INFO: Default tablespace DATA not found; using ' || v_default_ts || '.');
  end if;
  if v_temp_ts <> 'TEMP' then
    dbms_output.put_line('INFO: Temporary tablespace TEMP not found; using ' || v_temp_ts || '.');
  end if;

  select count(*) into v_exists from dba_profiles where profile = 'ORA_ADMIN_PROFILE';
  if v_exists = 0 then
    safe_exec('CREATE PROFILE ORA_ADMIN_PROFILE LIMIT SESSIONS_PER_USER DEFAULT');
  end if;
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT COMPOSITE_LIMIT DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT CONNECT_TIME DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT CPU_PER_CALL DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT CPU_PER_SESSION DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT FAILED_LOGIN_ATTEMPTS UNLIMITED');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT IDLE_TIME DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT INACTIVE_ACCOUNT_TIME DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT LOGICAL_READS_PER_CALL DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT LOGICAL_READS_PER_SESSION DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_GRACE_TIME 30');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_LIFE_TIME 360');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_LOCK_TIME 1');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_REUSE_MAX 4');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_REUSE_TIME 1');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_ROLLOVER_TIME DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PRIVATE_SGA DEFAULT');
  safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT SESSIONS_PER_USER DEFAULT');
  begin
    select count(*)
      into v_cloud_verify_exists
      from dba_objects
     where object_name = 'CLOUD_VERIFY_FUNCTION'
       and object_type = 'FUNCTION';
  exception
    when others then
      v_cloud_verify_exists := 0;
  end;
  if v_cloud_verify_exists > 0 then
    safe_exec('ALTER PROFILE ORA_ADMIN_PROFILE LIMIT PASSWORD_VERIFY_FUNCTION CLOUD_VERIFY_FUNCTION');
  else
    dbms_output.put_line('INFO: CLOUD_VERIFY_FUNCTION is not present. PASSWORD_VERIFY_FUNCTION left unchanged for ORA_ADMIN_PROFILE.');
  end if;

  select count(*) into v_user_exists from dba_users where username = v_target_username;
  if v_user_exists = 0 then
    safe_exec('CREATE USER ' || v_target_user_q || ' IDENTIFIED BY "' || replace(v_password, '"', '""') || '"');
    safe_exec('ALTER USER ' || v_target_user_q || ' DEFAULT TABLESPACE ' || v_default_ts);
    safe_exec('ALTER USER ' || v_target_user_q || ' TEMPORARY TABLESPACE ' || v_temp_ts);
    safe_exec('ALTER USER ' || v_target_user_q || ' PROFILE ORA_ADMIN_PROFILE');
    safe_exec('ALTER USER ' || v_target_user_q || ' ACCOUNT UNLOCK');
    :summary_user_action := 'Created user ' || v_target_username || ' and applied baseline account settings.';
    :summary_password_action := 'Set password during user creation.';
  else
    dbms_output.put_line('INFO: User ' || v_target_username || ' already exists. Existing account attributes are preserved; ADMIN-equivalent access will be appended.');
    :summary_user_action := 'Reused existing user ' || v_target_username || ' and appended ADMIN-equivalent access.';
    :summary_password_action := 'Left the existing password unchanged.';
  end if;
  if v_quota_ts is not null then
    safe_exec('ALTER USER ' || v_target_user_q || ' QUOTA UNLIMITED ON ' || v_quota_ts);
  end if;
  if v_setup_failed = 0 then
    :summary_setup_failures := null;
  else
    :summary_setup_failures := 'Setup failures (' || v_setup_failed || '):' || chr(10) || v_setup_failures;
  end if;
end;
/

prompt Processing optional ORDS enablement
declare
  v_target_username      varchar2(128) := upper(trim(q'[&&TARGET_USERNAME]'));
  v_target_user_q        varchar2(261);
  v_enable_ords          varchar2(20)  := upper(trim(q'[&&ENABLE_ORDS]'));
  v_auto_rest_auth       varchar2(20)  := upper(trim(q'[&&ORDS_AUTO_REST_AUTH]'));
  v_ords_metadata_exists number := 0;
  v_ords_admin_callable  number := 0;
  v_rest_auth_literal    varchar2(5);
  v_ords_notes           varchar2(4000);

  procedure append_ords_note(p_note in varchar2) is
  begin
    if p_note is null then
      return;
    end if;
    if v_ords_notes is null then
      v_ords_notes := p_note;
    elsif length(v_ords_notes) + length(p_note) + 2 <= 3900 then
      v_ords_notes := v_ords_notes || '; ' || p_note;
    end if;
  end;
begin
  if v_target_username is null then
    raise_application_error(-20000, 'TARGET_USERNAME must not be empty.');
  end if;
  if v_enable_ords not in ('Y', 'YES', 'TRUE', '1') then
    :summary_ords_action := 'Skipped ORDS enablement because ENABLE_ORDS is disabled.';
    return;
  end if;
  v_target_user_q := dbms_assert.enquote_name(dbms_assert.simple_sql_name(v_target_username), false);
  if v_auto_rest_auth in ('N', 'NO', 'FALSE', '0') then
    v_rest_auth_literal := 'FALSE';
  else
    v_rest_auth_literal := 'TRUE';
  end if;

  begin
    select count(*) into v_ords_metadata_exists from dba_users where username = 'ORDS_METADATA';
  exception
    when others then
      v_ords_metadata_exists := 0;
  end;

  if v_ords_metadata_exists > 0 then
    begin
      execute immediate 'GRANT INHERIT PRIVILEGES ON USER ' || v_target_user_q || ' TO ORDS_METADATA';
    exception
      when others then
        append_ords_note('INHERIT PRIVILEGES grant failed: ' || substr(sqlerrm, 1, 250));
    end;
  else
    append_ords_note('ORDS_METADATA user not found; skipped INHERIT PRIVILEGES grant');
  end if;

  begin
    select count(*)
      into v_ords_admin_callable
      from dba_objects
     where object_name = 'ORDS_ADMIN'
       and object_type in ('PACKAGE', 'SYNONYM', 'PUBLIC SYNONYM');
  exception
    when others then
      v_ords_admin_callable := 0;
  end;

  if v_ords_admin_callable > 0 then
    begin
      execute immediate
        'begin ords_admin.enable_schema(' ||
        'p_enabled => TRUE, ' ||
        'p_schema => ' || dbms_assert.enquote_literal(v_target_username) || ', ' ||
        q'[p_url_mapping_type => 'BASE_PATH', ]' ||
        'p_url_mapping_pattern => ' || dbms_assert.enquote_literal(lower(v_target_username)) || ', ' ||
        'p_auto_rest_auth => ' || v_rest_auth_literal ||
        '); end;';
      :summary_ords_action := 'Enabled ORDS with ORDS_ADMIN.ENABLE_SCHEMA.';
    exception
      when others then
        :summary_ords_action := 'Attempted ORDS enablement via ORDS_ADMIN but it failed: ' || sqlerrm;
    end;
  else
    :summary_ords_action := 'Skipped ORDS enablement because ORDS_ADMIN was not found.';
  end if;
  if v_ords_notes is not null then
    :summary_ords_action := rtrim(:summary_ords_action, '.') || '; ' || v_ords_notes || '.';
  end if;
end;
/

prompt Granting direct role grants
declare
    v_target_username varchar2(128) := upper(trim(q'[&&TARGET_USERNAME]'));
