prompt Granting explicit tablespace quotas
declare
    v_target_username varchar2(128) := upper(trim(q'[&&TARGET_USERNAME]'));
    v_target_user_q   varchar2(261);
    v_attempted       number := 0;
    v_failed          number := 0;
    v_failure_summary varchar2(4000);

    procedure append_failure(p_sql in varchar2, p_err in varchar2) is
      v_entry varchar2(500);
    begin
      v_failed := v_failed + 1;
      v_entry := '[' || to_char(v_failed) || '] ' || substr(p_sql, 1, 180) || ' -> ' || substr(p_err, 1, 180);
      if v_failure_summary is null then
        v_failure_summary := v_entry;
      elsif length(v_failure_summary) + length(v_entry) + 1 <= 3900 then
        v_failure_summary := v_failure_summary || chr(10) || v_entry;
      end if;
    end;

    function resolve_perm_ts(p_preferred in varchar2) return varchar2 is
      v_ts varchar2(128);
    begin
      begin
        select tablespace_name
          into v_ts
          from dba_tablespaces
         where contents = 'PERMANENT'
           and tablespace_name = upper(p_preferred);
        return v_ts;
      exception
        when no_data_found then
          null;
      end;
      select tablespace_name
        into v_ts
        from (
          select tablespace_name
            from dba_tablespaces
           where contents = 'PERMANENT'
           order by case when tablespace_name = 'USERS' then 0 else 1 end, tablespace_name
        )
       where rownum = 1;
      return v_ts;
    exception
      when no_data_found then
        return null;
    end;

    procedure safe_exec(p_sql in varchar2) is
      v_ts_name       varchar2(128);
      v_target_ts     varchar2(128);
      v_exists        number;
      v_effective_sql varchar2(4000);
    begin
      v_attempted := v_attempted + 1;
      v_effective_sql := p_sql;
      v_ts_name := regexp_substr(v_effective_sql, ' ON ([^ ]+)$', 1, 1, null, 1);
      if v_ts_name is not null then
        select count(*)
          into v_exists
          from dba_tablespaces
         where tablespace_name = upper(v_ts_name);
        if v_exists = 0 then
          if upper(v_ts_name) = 'DATA' then
            v_target_ts := resolve_perm_ts('DATA');
            if v_target_ts is not null and upper(v_target_ts) <> upper(v_ts_name) then
              v_effective_sql := regexp_replace(v_effective_sql, ' ON [^ ]+$', ' ON ' || v_target_ts);
            else
              append_failure(p_sql, 'Skipped because tablespace DATA does not exist and no fallback permanent tablespace was found.');
              return;
            end if;
          else
            append_failure(p_sql, 'Skipped because tablespace does not exist in target database.');
            return;
          end if;
        end if;
      end if;
      execute immediate v_effective_sql;
    exception
      when others then
        append_failure(v_effective_sql, sqlerrm);
    end;
  begin
    if v_target_username is null then
      raise_application_error(-20000, 'TARGET_USERNAME must not be empty.');
    end if;
    v_target_user_q := dbms_assert.enquote_name(dbms_assert.simple_sql_name(v_target_username), false);
    safe_exec('ALTER USER ' || v_target_user_q || ' QUOTA UNLIMITED ON DATA');
    :quota_changes_attempted := nvl(:quota_changes_attempted, 0) + v_attempted;
    :quota_changes_failed := nvl(:quota_changes_failed, 0) + v_failed;
    if v_failure_summary is not null then
      if :summary_quota_failures is null then
        :summary_quota_failures := v_failure_summary;
      elsif length(:summary_quota_failures) + length(v_failure_summary) + 1 <= 3900 then
        :summary_quota_failures := :summary_quota_failures || chr(10) || v_failure_summary;
      end if;
    end if;
end;
/

prompt Granting direct object grants
declare
    v_target_username varchar2(128) := upper(trim(q'[&&TARGET_USERNAME]'));
    v_target_user_q   varchar2(261);
    v_attempted       number := 0;
    v_failed          number := 0;
    v_failure_summary varchar2(4000);

    procedure append_failure(p_sql in varchar2, p_err in varchar2) is
      v_entry     varchar2(500);
      v_on_pos    pls_integer;
      v_to_pos    pls_integer;
      v_on_clause varchar2(500);
    begin
      v_failed := v_failed + 1;
      v_on_pos := instr(p_sql, ' ON ');
      v_to_pos := instr(p_sql, ' TO ');
      if v_on_pos > 0 and v_to_pos > v_on_pos then
        v_on_clause := substr(p_sql, v_on_pos + 4, v_to_pos - (v_on_pos + 4));
      end if;
      if regexp_like(v_on_clause, '^"APEX_[^"]+"\."') then
        :object_apex_failures := nvl(:object_apex_failures, 0) + 1;
        return;
      end if;
      if v_to_pos > 7 then
        v_entry := '[' || to_char(v_failed) || '] ' || substr(p_sql, 7, v_to_pos - 7) || ' -> ' || substr(p_err, 1, 140);
      else
        v_entry := '[' || to_char(v_failed) || '] ' || substr(p_sql, 1, 180) || ' -> ' || substr(p_err, 1, 140);
      end if;
      if v_failure_summary is null then
        v_failure_summary := v_entry;
      elsif length(v_failure_summary) + length(v_entry) + 1 <= 3900 then
        v_failure_summary := v_failure_summary || chr(10) || v_entry;
      end if;
    end;

    procedure safe_exec(p_sql in varchar2) is
    begin
      v_attempted := v_attempted + 1;
      execute immediate p_sql;
    exception
      when others then
        append_failure(p_sql, sqlerrm);
    end;
  begin
    if v_target_username is null then
      raise_application_error(-20000, 'TARGET_USERNAME must not be empty.');
    end if;
    v_target_user_q := dbms_assert.enquote_name(dbms_assert.simple_sql_name(v_target_username), false);
    safe_exec('GRANT EXECUTE ON "APEX_240200"."APEX" TO ' || v_target_user_q || ' WITH GRANT OPTION');
