    safe_exec('GRANT EXECUTE ON "C##CLOUD$SERVICE"."DBMS_CLOUD_OCI_DS_DATA_SAFE_LIST_TARGET_DATABASES_RESPONSE_T" TO ' || v_target_user_q || ' WITH GRANT OPTION');
