      if :summary_object_grant_failures is null then
        :summary_object_grant_failures := v_failure_summary;
      elsif length(:summary_object_grant_failures) + length(v_failure_summary) + 1 <= 3900 then
        :summary_object_grant_failures := :summary_object_grant_failures || chr(10) || v_failure_summary;
      end if;
    end if;
