    safe_exec('GRANT EXECUTE ON "C##CLOUD$SERVICE"."DBMS_CLOUD_OCI_OS_MANAGEMENT_INSTALLABLE_PACKAGE_SUMMARY_TBL" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT EXECUTE ON "C##CLOUD$SERVICE"."DBMS_CLOUD_OCI_OS_MANAGEMENT_INSTALLED_PACKAGE_SUMMARY_T" TO ' || v_target_user_q || ' WITH GRANT OPTION');
