/

declare
    v_target_username varchar2(128) := upper(trim(q'[&&TARGET_USERNAME]'));
    v_target_user_q   varchar2(261);
    v_attempted       number := 0;
    v_failed          number := 0;
    v_failure_summary varchar2(4000);

    procedure append_failure(p_sql in varchar2, p_err in varchar2) is
      v_entry     varchar2(500);
      v_on_pos    pls_integer;
      v_to_pos    pls_integer;
      v_on_clause varchar2(500);
    begin
      v_failed := v_failed + 1;
      v_on_pos := instr(p_sql, ' ON ');
      v_to_pos := instr(p_sql, ' TO ');
      if v_on_pos > 0 and v_to_pos > v_on_pos then
        v_on_clause := substr(p_sql, v_on_pos + 4, v_to_pos - (v_on_pos + 4));
      end if;
      if regexp_like(v_on_clause, '^"APEX_[^"]+"\."') then
        :object_apex_failures := nvl(:object_apex_failures, 0) + 1;
        return;
      end if;
      if v_to_pos > 7 then
        v_entry := '[' || to_char(v_failed) || '] ' || substr(p_sql, 7, v_to_pos - 7) || ' -> ' || substr(p_err, 1, 140);
      else
        v_entry := '[' || to_char(v_failed) || '] ' || substr(p_sql, 1, 180) || ' -> ' || substr(p_err, 1, 140);
      end if;
      if v_failure_summary is null then
        v_failure_summary := v_entry;
      elsif length(v_failure_summary) + length(v_entry) + 1 <= 3900 then
        v_failure_summary := v_failure_summary || chr(10) || v_entry;
      end if;
    end;

    procedure safe_exec(p_sql in varchar2) is
    begin
      v_attempted := v_attempted + 1;
      execute immediate p_sql;
    exception
      when others then
        append_failure(p_sql, sqlerrm);
    end;
