    safe_exec('GRANT SELECT ON "SYS"."CDB_WORKLOAD_TRACKED_COMMITS" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT SELECT ON "SYS"."CDB_WORKLOAD_USER_MAP" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT SELECT ON "SYS"."CDB_XDS_ACL_REFRESH" TO ' || v_target_user_q || ' WITH GRANT OPTION');
