    safe_exec('GRANT SELECT ON "SYS"."GV_$SYSTEM_PARAMETER2" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT SELECT ON "SYS"."GV_$SYSTEM_RESET_PARAMETER" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT SELECT ON "SYS"."GV_$SYSTEM_RESET_PARAMETER2" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT SELECT ON "SYS"."GV_$SYSTEM_WAIT_CLASS" TO ' || v_target_user_q || ' WITH GRANT OPTION');
