    safe_exec('GRANT READ ON "SYS"."USER_ANALYTIC_VIEW_CLC_MEAS" TO ' || v_target_user_q || ' WITH GRANT OPTION');
    safe_exec('GRANT READ ON "SYS"."USER_ANALYTIC_VIEW_CLC_MEAS_AE" TO ' || v_target_user_q || ' WITH GRANT OPTION');
