prompt Completed ADMIN recreation script
prompt Parsed counts from full_report.txt:
prompt   direct roles            = 69
prompt   direct system privs     = 287
prompt   direct object grants    = 29807
prompt   tablespace quota rows   = 1

begin
  dbms_output.put_line(' ');
  dbms_output.put_line('Summary');
  dbms_output.put_line('Target user: ' || upper('&&TARGET_USERNAME'));
  dbms_output.put_line('User action: ' || :summary_user_action);
  dbms_output.put_line('Password action: ' || :summary_password_action);
  dbms_output.put_line('ORDS: ' || :summary_ords_action);
  dbms_output.put_line('Role grants: attempted ' || to_char(nvl(:role_grants_attempted, 0)) || ', succeeded ' || to_char(nvl(:role_grants_attempted, 0) - nvl(:role_grants_failed, 0)) || ', failed ' || to_char(nvl(:role_grants_failed, 0)) || '.');
  dbms_output.put_line('System privileges: attempted ' || to_char(nvl(:sys_privs_attempted, 0)) || ', succeeded ' || to_char(nvl(:sys_privs_attempted, 0) - nvl(:sys_privs_failed, 0)) || ', failed ' || to_char(nvl(:sys_privs_failed, 0)) || '.');
  dbms_output.put_line('Tablespace quotas: attempted ' || to_char(nvl(:quota_changes_attempted, 0)) || ', succeeded ' || to_char(nvl(:quota_changes_attempted, 0) - nvl(:quota_changes_failed, 0)) || ', failed ' || to_char(nvl(:quota_changes_failed, 0)) || '.');
  dbms_output.put_line('Object grants: attempted ' || to_char(nvl(:object_grants_attempted, 0)) || ', succeeded ' || to_char(nvl(:object_grants_attempted, 0) - nvl(:object_grants_failed, 0)) || ', failed ' || to_char(nvl(:object_grants_failed, 0)) || '.');
  if :summary_setup_failures is null then
    dbms_output.put_line('Setup failures: none.');
  else
    dbms_output.put_line('Setup failures:' || chr(10) || :summary_setup_failures);
  end if;
  if :summary_role_failures is null then
    dbms_output.put_line('Roles do not exist/not granted: none.');
  else
    dbms_output.put_line('Roles do not exist/not granted: ' || :summary_role_failures);
  end if;
  if :summary_sys_priv_failures is null then
    dbms_output.put_line('System privileges unavailable/not granted: none.');
  else
    dbms_output.put_line('System privileges unavailable/not granted: ' || :summary_sys_priv_failures);
  end if;
  if :summary_quota_failures is null then
    dbms_output.put_line('Tablespace quota failures: none.');
  else
    dbms_output.put_line('Tablespace quota failures:' || chr(10) || :summary_quota_failures);
  end if;
  if :summary_object_grant_failures is null and nvl(:object_apex_failures, 0) = 0 then
    dbms_output.put_line('Object grants not applied: none.');
  else
    dbms_output.put_line('Object grants not applied:');
    if nvl(:object_apex_failures, 0) > 0 then
      dbms_output.put_line('APEX schema objects unavailable: ' || to_char(:object_apex_failures) || ' grants not applied.');
    end if;
    if :summary_object_grant_failures is not null then
      dbms_output.put_line(:summary_object_grant_failures);
    end if;
  end if;
  dbms_output.put_line('Script completed successfully.');
end;
/
